<section class="section"><div class="section-heading"><div><p class="eyebrow">YOUR EVERYDAY, IN THE MAKING</p><h1>Your bag.</h1></div><a class="underlined" href="/shop">Keep exploring ↗</a></div><?php $items=Commerce::cart(); if(!$items): ?><div class="empty-state"><span>◇</span><h2>A little room for something good.</h2><p>Your bag is waiting for your next favorite.</p><a class="btn" href="/shop">Discover WIKI ↗</a></div><?php else: $couponError=null; try { $totals=Commerce::totals($items,$_SESSION['coupon']??''); } catch(DomainException $ex) { $couponError=$ex->getMessage(); unset($_SESSION['coupon']); $totals=Commerce::totals($items); } ?><div class="checkout-grid"><div><?php foreach($items as $i): ?><article class="cart-line"><a href="/product/<?=e($i['slug'])?>"><img src="<?=e(image_path($i))?>" alt="<?=e($i['name'])?>" width="140" height="175"></a><div><h3><?=e($i['name'])?></h3><p><?=e(trim($i['size'].' '.$i['color'].' '.$i['volume']))?></p><p><?=money($i['unit_price'])?></p><form method="post" action="/api/action" data-ajax data-reload><?=csrf_field()?><input type="hidden" name="action" value="cart"><input type="hidden" name="variant_id" value="<?=e($i['id'])?>"><label class="inline-label">Qty <input name="quantity" type="number" value="<?=e($i['quantity'])?>" min="0" max="<?=min(20,$i['stock'])?>"></label><button class="text-button">Update</button><small>Set to 0 to remove</small></form><?php if($i['quantity']>$i['stock']): ?><p class="error">Stock has changed. Please reduce quantity.</p><?php endif ?></div><strong><?=money($i['line_total'])?></strong></article><?php endforeach ?><form method="post" action="/api/action" data-ajax data-reload data-confirm="Remove all items from your bag?"><?=csrf_field()?><input type="hidden" name="action" value="clear-cart"><button class="text-button">Clear bag</button></form></div><aside class="order-summary"><h2>The summary</h2><?php require ROOT.'/views/partials/totals.php'; ?><form method="post" action="/api/action" data-ajax data-reload><?=csrf_field()?><input type="hidden" name="action" value="coupon"><label>Have a code?<input name="code" placeholder="Enter your code" value="<?=e($_SESSION['coupon']??'')?>" maxlength="40"></label><button class="text-button">Apply code →</button><small>Sign in to redeem a coupon. Leave blank to remove.</small></form><?php if($couponError): ?><p class="error"><?=e($couponError)?></p><?php endif ?><a class="btn full" href="/checkout">Continue to checkout ↗</a><p class="muted">Secure checkout · Cash on delivery</p></aside></div><?php endif ?></section>
